import{_ as a,C as s,o as n,c as i,ag as e,E as r}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Product Management","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-management.md","filePath":"catalog/product-management.md","lastUpdated":1787558413000}'),l={name:"catalog/product-management.md"};function g(d,t,c,u,p,h){const o=s("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="product-management" tabindex="-1">Product Management <a class="header-anchor" href="#product-management" aria-label="Permalink to &quot;Product Management&quot;">​</a></h1><p>Product Management is where a seller builds and maintains their catalog — creating listings, editing every detail, tracking approval, and keeping stock and pricing current. Everything a seller lists passes through the admin&#39;s approval before it reaches the storefront.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What the products list shows and how to act on it</li><li>The two ways to add a product, and the guided &quot;List Your Product&quot; flow</li><li>Every section of the product form and how listings get approved</li></ul></div><h2 id="the-products-list" tabindex="-1">The products list <a class="header-anchor" href="#the-products-list" aria-label="Permalink to &quot;The products list&quot;">​</a></h2><p>From the Seller Panel, open <strong>Catalog → Products</strong>. This is every product the seller owns or has assigned, each row showing its image, <strong>name / SKU / product number</strong>, <strong>price</strong>, <strong>stock</strong>, <strong>status</strong> (Active / Disable), <strong>approval</strong> state, <strong>draft</strong> state, <strong>type</strong>, <strong>category</strong>, and <strong>barcode</strong>.</p>',5)),r(o,{src:"/images/product-management/products-list.png",alt:"Seller products list"}),t[1]||(t[1]=e('<ul><li><strong>Search</strong> and <strong>Filter</strong> narrow the list — including filters for approval (<strong>Approved / Waiting For Approval / Rejected</strong>) and draft (<strong>Draft / Submitted</strong>).</li><li>The row menu lets you <strong>Edit</strong> or <strong>Delete</strong> a product.</li><li><strong>Checkboxes</strong> enable bulk actions: <strong>Delete</strong>, <strong>Generate Barcode</strong>, and <strong>Print Barcodes</strong> (see <a href="/catalog/product-barcode">Product Barcode</a>).</li></ul><div class="info custom-block"><p class="custom-block-title">Owned vs assigned</p><p>Deleting a product you <strong>created</strong> removes it from the catalog. Deleting one you&#39;re only <strong>reselling</strong> (assigned) just removes your listing — the underlying catalog product stays. See <a href="/catalog/selling-existing-products">Selling Existing Products</a>.</p></div><h2 id="adding-a-product" tabindex="-1">Adding a product <a class="header-anchor" href="#adding-a-product" aria-label="Permalink to &quot;Adding a product&quot;">​</a></h2><p>Product creation starts from <strong>Catalog → List Your Product</strong>. The launcher offers three ways to add products:</p>',4)),r(o,{src:"/images/product-management/create-launcher.png",alt:"List Your Product launcher"}),t[2]||(t[2]=e('<ul><li><strong>Create New Products</strong> — build a brand-new listing from scratch with a short guided flow.</li><li><strong>Search Products</strong> — list something already in the marketplace catalog as your own. See <a href="/catalog/selling-existing-products">Selling Existing Products</a>.</li><li><strong>Bulk Upload</strong> — add many products at once from a spreadsheet. See <a href="/catalog/bulk-upload">Bulk Upload</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Complete your profile first</p><p>The create flow is only available once your seller profile is complete. If it isn&#39;t, the launcher prompts you to <strong>update your profile details</strong> before you can list a product. If a subscription plan caps your catalog, you&#39;re also stopped once you reach your plan&#39;s product limit.</p></div><h3 id="the-what-kind-of-product-funnel" tabindex="-1">The &quot;What kind of product?&quot; funnel <a class="header-anchor" href="#the-what-kind-of-product-funnel" aria-label="Permalink to &quot;The &quot;What kind of product?&quot; funnel&quot;">​</a></h3><p>Choosing <strong>Create New Products</strong> opens a plain-language funnel that maps your answers to the right Bagisto product type behind the scenes:</p>',4)),r(o,{src:"/images/product-management/scratch-funnel.png",alt:"What kind of product funnel"}),t[3]||(t[3]=e('<ol><li><strong>What kind of product are you selling?</strong> — pick one of six kinds: <ul><li><strong>Physical Product</strong> — a tangible item you ship (a <em>simple</em> product; can have variations).</li><li><strong>Digital Download</strong> — a downloadable file such as an e-book or software.</li><li><strong>Service or Membership</strong> — an intangible offering with no shipping.</li><li><strong>Bookable</strong> — a product customers reserve for a date or time. See <a href="/orders/booking-management">Booking Management</a>.</li><li><strong>Bundle</strong> — several products sold together as one package.</li><li><strong>Grouped Products</strong> — a set of related products shown together.</li></ul></li><li><strong>Does this product have variations?</strong> — for a physical product, answer <strong>Yes</strong> to create variants (size, colour, …) or <strong>No</strong> for a single item.</li><li><strong>Which attribute family</strong> the product belongs to, and — for a variable product — <strong>which attributes will vary</strong>.</li><li><strong>What SKU would you like to use?</strong></li></ol><p>Select <strong>Continue</strong> and the product opens on the edit form, created as a <strong>draft</strong> so you can finish it privately.</p><h2 id="the-product-form" tabindex="-1">The product form <a class="header-anchor" href="#the-product-form" aria-label="Permalink to &quot;The product form&quot;">​</a></h2><p>The edit form is where the listing takes shape. A <strong>Listing Completeness</strong> bar at the top shows how much is filled in — a more complete listing gets more visibility and is easier to approve.</p><p>The form comes in two shapes, and which one a seller gets is the admin&#39;s choice:</p><ul><li><strong>Stepped</strong> — the listing is split into two phases, <strong>Product Basics → Complete Listing</strong>, with tabbed sections inside each. A progress bar tracks how far through the seller is.</li><li><strong>Two Column</strong> — the classic single-page form with every section laid out in two columns.</li></ul><p>The admin sets the default under <strong>Configure → Marketplace → Products → Product Form</strong> and can override it for individual attribute families — see <a href="/catalog/product-form-layout">Product Form Layout</a>. The sections below are the same either way; only their arrangement changes.</p>',7)),r(o,{src:"/images/product-management/edit-general.png",alt:"Product edit form — General"}),t[4]||(t[4]=e('<p>The header carries the key actions: <strong>Back</strong>, <strong>Preview</strong> (opens the storefront page once the product is active and visible), a Magic AI <strong>Generate content</strong> button where enabled (<a href="/catalog/magic-ai">Magic AI</a>), and — depending on state — <strong>Save as Draft</strong> / <strong>Submit</strong> for a draft, or <strong>Save Product</strong> for a live one. A <strong>channel</strong> and <strong>locale</strong> switcher let you edit per-channel and per-language values.</p><p>The tabbed sections are:</p><ul><li><strong>General</strong> — SKU, product number, name, URL key, tax category, and the family&#39;s other core attributes.</li><li><strong>Price</strong> — the selling price, cost, and special (sale) price with a date range, plus a <strong>Customer Group Price</strong> panel for tiered pricing (fixed or discount, per quantity, for all or specific customer groups). For bulk pricing across products, see <a href="/pricing/manage-pricing">Manage Pricing</a>.</li></ul>',3)),r(o,{src:"/images/product-management/edit-price.png",alt:"Product edit form — Price"}),t[5]||(t[5]=e('<ul><li><strong>Description</strong> — the short and full descriptions (rich-text). Sellers with access can draft these with <a href="/catalog/magic-ai">Magic AI</a>.</li><li><strong>Meta Description</strong> — meta title, keywords, and description for SEO.</li><li><strong>Shipping</strong> — weight and dimensions used for shipping calculations.</li><li><strong>Settings</strong> — toggles such as New, Featured, Visible Individually, Status, and Guest Checkout.</li><li><strong>Inventories</strong> — stock per inventory source, with a &quot;pending ordered quantity&quot; hint. See <a href="/inventory/manage-inventory">Manage Inventory</a>.</li><li><strong>RMA</strong> — the product&#39;s return policy: a <strong>Status</strong> toggle and, when on, a <strong>Rule</strong> that governs returns. See <a href="/orders/return-merchandise-authorization">Returns (RMA)</a>.</li></ul>',1)),r(o,{src:"/images/product-management/edit-rma.png",alt:"Product edit form — RMA"}),t[6]||(t[6]=e('<ul><li><strong>Barcode</strong> — the product&#39;s barcode value and its auto-generated image. See <a href="/catalog/product-barcode">Product Barcode</a>.</li><li><strong>Media</strong> — product images (suggested resolution 609 × 560 px) and video.</li><li><strong>Organization</strong> — the channels the product belongs to, its categories (searchable tree), and related / up-sell / cross-sell links.</li></ul><p>Depending on the product kind, a <strong>type-specific</strong> section also appears — for example <strong>Variations</strong> for a configurable product (add variants, generate combinations, set per-variant price/stock), downloadable <strong>Links &amp; Samples</strong>, bundle items, grouped products, or booking availability.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the <strong>Listing Completeness</strong> bar as close to 100% as you can before submitting — complete listings rank better and are quicker for the admin to approve.</p></div><h2 id="drafts-submission-and-approval" tabindex="-1">Drafts, submission, and approval <a class="header-anchor" href="#drafts-submission-and-approval" aria-label="Permalink to &quot;Drafts, submission, and approval&quot;">​</a></h2><p>Three admin settings under <strong>Configure → Marketplace → Products → Approval &amp; Creation</strong> govern this whole flow:</p><ul><li><strong>Approval Required</strong> — whether a submitted product waits for the admin before going live. With it off, submitted products publish straight away.</li><li><strong>Seller Can Create Product</strong> — whether sellers may build brand-new listings at all.</li><li><strong>Seller Can Assign Product</strong> — whether sellers may list existing catalog products as their own. See <a href="/catalog/selling-existing-products">Selling Existing Products</a>.</li></ul>',6)),r(o,{src:"/images/product-management/products-config.png",alt:"Marketplace product configuration — Approval & Creation, Product Form and Inventory settings"}),t[7]||(t[7]=e('<p>With those in place:</p><ul><li><strong>Save as Draft</strong> keeps a work-in-progress private — it isn&#39;t sent for approval and never shows on the storefront. See <a href="/catalog/draft-products">Draft Products</a>.</li><li><strong>Submit</strong> sends the product into the <strong>approval</strong> flow. Until the admin approves it, the products list shows it as <strong>Waiting For Approval</strong>.</li><li>The admin reviews products under <strong>Marketplace → Catalog → Products</strong> in the admin panel. Once approved, the product goes live; if <strong>rejected</strong>, the admin attaches a reason and the listing shows as <strong>Rejected</strong> so you know what to fix before resubmitting.</li></ul>',2))])}const _=a(l,[["render",g]]);export{f as __pageData,_ as default};
